import{_ as n,o as e,c as t,a3 as s}from"./chunks/framework.Dz5Q8p4s.js";const m=JSON.parse('{"title":"UI2V-Bench: An Understanding-based Image-to-video Generation Benchmark","description":"","frontmatter":{"title":"UI2V-Bench: An Understanding-based Image-to-video Generation Benchmark","arxiv":"2509.24427","date":"2025-09-29","authors":"Ailing Zhang, Lina Lei, Dehong Kong, Zhixin Wang, Jiaqi Xu, Fenglong Song, Chun-Le Guo, Chang Liu, Fan Li, Jie Chen","categories":"cs.CV","topics":"图生视频评测, 语义理解, 因果推理","outline":[2,2]},"headers":[],"relativePath":"papers/2509.24427.md","filePath":"papers/2509.24427.md","lastUpdated":null}'),r={name:"papers/2509.24427.md"};function o(i,a,p,l,d,g){return e(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="ui2v-bench-an-understanding-based-image-to-video-generation-benchmark" tabindex="-1">UI2V-Bench: An Understanding-based Image-to-video Generation Benchmark <a class="header-anchor" href="#ui2v-bench-an-understanding-based-image-to-video-generation-benchmark" aria-label="Permalink to &quot;UI2V-Bench: An Understanding-based Image-to-video Generation Benchmark&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2509.24427" target="_blank" rel="noreferrer">2509.24427</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-09-29</td></tr><tr><td><strong>作者</strong></td><td>Ailing Zhang, Lina Lei, Dehong Kong, Zhixin Wang, Jiaqi Xu, Fenglong Song, Chun-Le Guo, Chang Liu, Fan Li, Jie Chen</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>把 I2V 评测从「画质与时序」换成「模型是否真读懂了输入图」，用 GroundingDINO+SAM2+VideoRefer 的实例级流水线测语义定位，用可观测 yes/no 问题链测因果推理。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>I2V 比 T2V 更贴近真实用法：用户手里通常已经有一张图，只是想让它动起来。但这也带来一个 T2V 不存在的评测缺口——模型必须先看懂图里有什么、谁在哪儿、哪个是「红色的气球」，然后才谈得上生成。现有 I2V benchmark（AIGCBench、AnimateBench、VBench-I2V、TC-Bench）测的是画质、时序一致性、运动平滑度和 CLIP 相似度，这些指标对「模型把左边的狗和右边的狗搞反了」几乎不敏感。</p><p>论文要补的是两件被系统性忽略的能力。第一是<strong>细粒度语义定位</strong>：prompt 说「左边的狗坐下」，模型得先在图里定位左边那只狗，再只让它动。第二是<strong>因果推理</strong>：prompt 给的是「原因」（「扣动扳机」「松开气球」「香蕉放了一周」），模型要生成符合物理与常识的「结果」。第二点尤其重要——它把 I2V 评测和世界模型的核心诉求接上了：一个能正确外推「松手之后气球会飞走」的生成器，才具备被当作物理模拟器的最低资格。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>I2V 模型侧发展很快：Wan2.1、HunyuanVideo、CogVideoX 在开源侧，Seedance、Hailuo 在商用侧。评测侧则明显滞后。传统指标（IS、LPIPS、FID、FVD）只刻画分布距离与感知相似度。T2V 侧的 benchmark 相对成熟（VBench、EvalCrafter、FETV、T2V-CompBench），但直接搬到 I2V 会漏掉图像条件这一半信息。</p><p>I2V 专用的三条线各有短板，作者点得很具体：AIGCBench 与 AnimateBench 主要依赖 CLIP 类分数，而 CLIP 是全局对齐，对「哪个主体在动」这种实例级问题天然不敏感；TC-Bench 测的是 temporal compositionality，关注属性随时间的组合变化而非输入图的语义理解；VBench-I2V 把输入图与生成视频拆成前景/背景来算一致性，这是外观层面的度量，与「模型有没有理解 prompt 指的是哪一个主体」正交。三者共同的盲区是同一个：<strong>它们都不检验模型是否真的读懂了输入图</strong>。</p><p>还有一层更隐蔽的缺口。所有现有指标都假设生成质量与语义正确性正相关，因此高画质模型自然拿高分。论文用实验直接反驳了这个假设（见 §7），这也是为什么单靠改良现有指标不够，必须换评测范式。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>在本文之前，社区已经积累了三样可以直接用的东西。第一，开放词表检测与分割（GroundingDINO、SAM2）已经足够可靠，可以把「红色的气球」从图里抠出来。第二，视频描述模型（Tarsier）与时空对象理解模型（VideoRefer）已经能对<strong>指定区域</strong>生成描述，而不只是对整段视频给一句 caption。第三，MLLM 做多轮 QA 式评测已经是常规操作。</p><p>一个认真的研究者会先做一件事：拿现有 benchmark 跑一批模型，看排名是否和自己的主观感受一致。当发现一个画质很好的模型经常把错误的主体动起来、而指标丝毫不降时，问题的定位就清晰了——<strong>全局指标无法惩罚实例级错误</strong>。修法也随之明确：既然已有工具能定位实例，就先定位再描述再判断，把评测粒度从整帧压到单个主体。这就是实例级流水线的来源。</p><p>推理维度的路径不同。作者观察到两个具体失败模式：MLLM 因文本偏置容易顺着 prompt 承认视频里有其实没有的内容；以及<strong>结果本身可能物理上不可见</strong>——「狙击手扣动扳机」后子弹因为速度太快根本不会出现在帧里，直接问「子弹打中目标了吗」必然误判。这两点合起来指向同一个修法：不要直接问最终结果，改问一串可观测的中间现象（有没有扣扳机的手部动作？有没有后坐力？有没有火光？），再由这些可观测量合成对最终结果的判断。这本质上是把不可观测的因果链替换成可观测的代理链。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>评测 I2V 的难点在于「对不对」发生在实例层，而指标算在全局层，两者中间隔着一层不可约的粒度差。把主体先分割出来再描述，粒度差就消失了。至于因果推理，问题在于因果链的终点往往不可见，于是把一个不可判定的问题（子弹打中了吗）拆成一串可判定的问题（有后坐力吗、有火光吗），用中间证据的通过率去逼近最终判断。两条修法是同一个思路的两面：把无法直接测量的东西换成可以直接测量的东西。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>维度设计</strong>。四个主维度、9 个 aspect、19 个细分子维度，约 500 对文本–图像输入。图像主要来自 Unsplash 与 Pexels，少量复杂场景（如「苹果排成一圈」）由 GPT-4 生成。</p><ul><li><em>Spatial Understanding</em>：图中同类主体呈线性排列（左右或上下），prompt 用序数位置指定目标（「左边的狗坐下，右边的狗保持不动」）。为防止类别线索泄露空间信息，所有主体强制同类；主体数 2–4 个。</li><li><em>Attribute Binding</em>：同类主体靠属性区分。人物侧包含年龄、身高、体型、着装、妆容、情绪、姿态、持物；物体侧包含颜色、尺寸、形状、材质、纹理/图案、状态（空杯 vs 有水的杯）。</li><li><em>Category Understanding</em>：图中含多个不同类别的常见物体（胡萝卜、苹果、香蕉），要求定位并保持时序身份一致（「移走胡萝卜」「男人拿起咖啡杯」）。</li><li><em>Reasoning</em>：四个子维度——Human Society（意图与社会关系，「弓箭手松开弓弦」）、Physical Interactions（力学、流体、重力，「松开气球」）、Temporal Changes（生命过程、环境变化、物态转变，「香蕉在外面放了一周」）、Natural Environment（动植物行为与生态，「蜜蜂落在花上采蜜」）。此维度的 prompt 不再描述要驱动哪个主体，而是给出一个「因」，让模型生成「果」。</li></ul><p><strong>实例级评测流水线</strong>（用于前三个维度），以「红色的气球飘起来」为例：</p><ol><li><em>Prompt Analyzer</em>：MLLM 抽取主体关键词（red balloon）与动作关键词（float up）。</li><li><em>Subject Segmentor</em>：GroundingDINO 用主体关键词做开放词表检测，SAM2 输出目标掩码。</li><li><em>Action Descriptor</em>：把掩码送进 VideoRefer（时空对象理解 video-LLM，而非通用 MLLM），生成针对该主体的动作与外观描述。</li><li><em>Result Judge</em>：MLLM 比对该描述与原 prompt，输出分数。</li></ol><p><strong>反馈式推理评测流水线</strong>（用于 Reasoning），以「狙击手扣动扳机」为例：</p><ol><li><em>Video Description</em>：Tarsier 生成整段视频的详细描述。</li><li><em>Question Chain Generation</em>：LLM 依据 prompt 与预设 target 生成一串二值判断题，每题必须对应可观测现象——「是否有扣动扳机的手部动作？」「枪身是否有明显后坐力？」「是否有火光？」，最后才是「判断子弹是否已发射」。</li><li><em>Evaluation Score</em>：结合视频描述与问题链，对最终结果与中间反馈联合打分。</li></ol><p><strong>被测模型</strong>：开源侧 Wan2.1-14B（480p / 24 fps / 5 s）、HunyuanVideo（720p / 24 fps / 3 s）、CogVideoX1.5-5B（768×1360 / 8 fps / 6 s）；闭源侧 Seedance-1.0-pro（580p / 25 fps / 5 s）、MiniMax-Hailuo-02（768p / 24 fps / 6 s）。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：闭源与开源差距有多大，排名是否合理？</strong> 表 2 最后一列是作者定义的 Image Understanding（四维平均，列名在 HTML 抓取中丢失，按正文描述反推），依次为 HunyuanVideo 28.49、CogVideoX 32.93、Wan2.1 38.68、SeedDance 41.67、Hailuo 46.30。开源侧 Wan2.1 领先，CogVideoX 在推理维度略优于 HunyuanVideo；闭源侧 Hailuo 明显优于 SeedDance，尤其在 Temporal Changes 上。Attribute Binding 单表的平均分为 HunyuanVideo 34.91、CogVideoX 40.05、SeedDance 39.33、Wan2.1 43.74、Hailuo 44.69——注意这里 SeedDance 反被 Wan2.1 超过，说明属性绑定与整体理解能力并不同向。</p><p><strong>问题二：现有画质指标够不够？</strong> 不够，而且方向会反。作者的结论是：对语义理解维度，基础指标无法衡量输出对 prompt 细粒度信息的响应；对推理维度，<strong>生成质量与语义对齐已经不再正相关</strong>。表 2 里前几列（VBench 的 image quality / aesthetic / motion smoothness 与 AIGCBench 的 video-text consistency / video-image similarity）在五个模型间差异很小（例如 motion smoothness 全部在 0.986–0.994 之间），而 Image Understanding 从 28.49 到 46.30 拉开了近 18 分。可以推断，传统指标已经饱和到无法区分这一代模型。</p><p><strong>问题三：问题链是不是必要的？</strong> 附录表 4 给出问题链得分的平均值：Wan2.1 46.37、HunyuanVideo 40.27、CogVideoX 42.35、SeedDance 58.02、Hailuo 69.89。作者称「问题链分数与最终分数基本一致」，这既是可信度证据，也留下一个疑问——若两者高度一致，中间反馈的边际价值到底有多大（见 §11）。</p><p><strong>问题四：自动指标与人类判断一致吗？</strong> 每个样本至少 8 名评测员，19 个指标各按 1–5 打分并做用户内归一化。表 3 报告 Kendall&#39;s <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span> 与 Spearman&#39;s <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span></span></span></span>：Spatial Understanding 0.6052 / 0.7345，Attribute Binding 0.2980 / 0.3566，Category Understanding 0.5729 / 0.6683，Reasoning 0.6121 / 0.7329，平均 0.5220 / 0.6231。作者强调 Spatial 与 Reasoning 对齐最强，这与数字一致；但<strong>Attribute Binding 的相关性只有 0.30/0.36，明显偏低</strong>，论文正文用「exhibit high correlations」一笔带过，没有单独讨论。结合附录 D 承认的开放词表检测困难（「从上往下第二把刀」「坐着的那个人」难以被准确检出），可以推断属性维度的低相关来自 Subject Segmentor 的定位失败。</p><p>值得记录的一处文本瑕疵：附录 B 的人工打分标准里，(3) Moderate 与 (4) Good 的描述文字完全相同（均为「目标主体运动错误，但其他物体保持静止」），这显然是笔误，也意味着人工标注的中间档判据在论文中无法被复现。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：UI2V-Bench 把 I2V 评测的重心从画质与时序移到「模型是否读懂了输入图」，设四个主维度（空间理解、属性绑定、类别理解、推理）、9 个 aspect、19 个子维度、约 500 对文本–图像输入。语义理解三维用实例级流水线评测：MLLM 抽关键词 → GroundingDINO+SAM2 出掩码 → VideoRefer 对该主体生成描述 → MLLM 判分。推理维度用反馈式问题链，把不可观测的因果终点（子弹是否命中）拆成可观测的中间现象（后坐力、火光）逐条验证。五个被测模型的 Image Understanding 从 28.49 到 46.30 拉开近 18 分，而传统画质指标几乎无差别。人类相关性在空间（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span>=0.61）与推理（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span>=0.61）维度最强，属性绑定最弱（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span>=0.30），后者与开放词表检测的定位失败直接相关。</p><p><strong>3 句话版</strong>：全局指标无法惩罚实例级语义错误，所以先分割主体再对该主体描述再判分。因果推理的终点常常不可见，所以改测可观测的中间证据链。基准揭示画质指标已经饱和，而理解能力差异巨大。</p><p><strong>1 句话版</strong>：I2V 模型的真正短板不是画得不够好，而是没看懂图；要测出这一点，评测的粒度必须下沉到实例。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的假设是：<strong>开放词表检测器能按 prompt 里的描述准确定位目标主体</strong>。整条实例级流水线的后三步全部建立在第一步的掩码正确之上；掩码错了，VideoRefer 会去描述一个错误的对象，Result Judge 会拿着这段描述与原 prompt 比对，最终给出一个看似合理实则毫无意义的分数。更糟的是这种失败不会报错，只会表现为分数偏低——于是<strong>检测器的失败与被测模型的失败在指标上不可区分</strong>。</p><p>论文自己在附录 D 承认了这一点，明确指出「从上往下第二把刀」「坐着的那个人」这类指代对检测器构成显著挑战，而准确检出是整套指标成立的前提。表 3 给出了间接的量化证据：属性绑定维度的 Kendall&#39;s <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span> 只有 0.2980，是四个维度里唯一明显偏低的，而属性绑定恰恰是最依赖细粒度指代（「蓝色眼影的女孩」「拿吉他的男人」）的维度。作者缺的证据是检测器本身的召回/准确率报告——没有这个数字，就无法把 benchmark 的噪声与被测模型的能力分开。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，目标是量化「检测器失败」占了多少分数损失：</p><ul><li><strong>数据</strong>：只取 Attribute Binding 维度的输入图（同类多主体 + 属性指代 prompt），约 100 对。不需要生成任何视频。</li><li><strong>实现</strong>：只跑流水线的第 1–2 步（Prompt Analyzer + GroundingDINO + SAM2），把输出掩码与人工标注的目标主体框做 IoU。</li><li><strong>测量</strong>：(i) 掩码定位准确率（IoU &gt; 0.5 视为正确），按属性类型分组（颜色 / 形状 / 材质 / 姿态 / 持物 / 序数位置）；(ii) 把定位正确与定位错误的样本分开，各自计算 benchmark 分数与人类分数的相关性。</li><li><strong>判据</strong>：若定位正确子集上的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span> 显著高于 0.30（比如接近空间维度的 0.61），而定位错误子集接近 0，则证明属性维度的低相关主要来自检测器而非指标设计，benchmark 只需换更强的 grounding 模型即可修复；若两个子集的相关性都低，则说明问题出在 Result Judge 的判分逻辑，需要重新设计。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击针对推理维度：<strong>问题链可能没有提供任何额外信息，只是把同一个判断做了多次</strong>。</p><p>替代解释来自论文自己的附录 A.2——作者说「问题链分数与最终分数基本一致」。如果中间证据链真的在纠正 MLLM 的文本偏置，我们应当观察到两者<strong>在特定样本上系统性分歧</strong>：视频里有扣扳机动作但没有后坐力，问题链应给出部分分，而直接判断会给零分或满分。高度一致恰恰暗示问题链没有改变结论，只是增加了 token 消耗。</p><p>具体实验：在 Reasoning 的 100 个样本上，同时跑三种评测——(a) 直接问 MLLM「视频是否正确呈现了 prompt 的结果」；(b) 完整问题链；(c) 问题链但把中间问题<strong>随机替换成与该 prompt 无关的可观测问题</strong>（例如对「扣扳机」样本问「画面里有没有出现绿色物体」）。比较三者与人类分数的 Kendall&#39;s <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span>。若 (b) 与 (c) 的相关性接近，说明增益来自「多步输出」这一格式而非中间证据的内容，问题链的因果 framing 被证伪；若 (b) 明显优于 (a) 且 (c) 接近 (a)，则论文的 claim 成立。</p><p>另有一类可预测的失败场景值得设计：<strong>中间证据齐全但最终结果错误</strong>。例如生成视频里手部动作、后坐力、火光俱全，但子弹飞向了与枪口相反的方向。按当前的「联合打分」规则，这类样本会因中间反馈全通过而拿到高分，而人类会判为严重错误。这暴露了代理链方法的结构性风险——用可观测代理替换不可观测目标，代价是代理与目标可能解耦。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>(a) 驱动的局限</strong>：UI2V-Bench 是<strong>离线且静态</strong>的——500 对固定输入，一次性打分。这有两个后果：一是被测模型迟早会对这批 prompt 过拟合；二是它只能告诉我们模型在这 19 个子维度上的平均表现，无法回答「这个模型的理解能力边界在哪里」。附录 D 承认只构建了线性排列的空间关系，正是这种静态设计的必然结果——每加一类关系都要重新造数据。</p><p><strong>(b) 可借鉴的相邻工具</strong>：软件测试里的<strong>属性驱动测试（property-based testing）与自动化用例最小化（delta debugging）</strong>。不预先枚举 500 个 case，而是定义一组不变量（「prompt 只指定一个主体时，其余主体的掩码 IoU 在时序上应保持稳定」「同一张图配互斥的两条 prompt，被驱动的主体应当不同」），再由搜索器自动生成、变异输入，主动寻找违反不变量的最小反例。评测的产物从「一张分数表」变成「一组该模型确定会失败的最小输入」。</p><p><strong>(c) 第一个实验</strong>：只用「同图互斥 prompt」这一条不变量。对同一张含 4 只同类动物的图，生成 4 条只在序数上不同的 prompt（左一 / 左二 / 右二 / 右一坐下），用 SAM2 追踪各主体的运动量，检验「被驱动主体」是否随 prompt 唯一变化。第一个观测量是<strong>不变量违反率</strong>，第二个是搜索器在多少步内能找到让模型必然混淆的主体排布（比如把主体间距压到某个阈值以下）。这个阈值就是模型空间理解能力的可量化边界，比一个 38.68 的平均分有用得多。</p>',51)])])}const c=n(r,[["render",o]]);export{m as __pageData,c as default};
